// ============================================
// 15MIN ALPHA TA EXTRACTOR v3 (OPTIMIZED + VOLUME PROFILE)
// Source: "ta_15m"
// Added: Volume Profile (S-Tier) - Patrick Neil strategy
// ============================================

const toNum = (v, d=null) => (v == null || Number.isNaN(+v)) ? d : parseFloat(Number(v).toFixed(8));
const last  = (arr) => (arr && arr.length ? arr[arr.length - 1] : null);

// --- helpers ---
const uniqSorted = (arr, asc=true) => [...new Set(arr.filter(x=>x!=null))].sort((a,b)=>asc?a-b:b-a);

// --- SMA ---
const sma = (values, period) => {
  if (!values || values.length < period) return [];
  const res = []; let sum = 0;
  for (let i=0;i<values.length;i++){
    sum+=values[i]; if(i>=period) sum-=values[i-period];
    if(i>=period-1) res.push(sum/period);
  }
  return res;
};

// --- EMA ---
const ema = (values, period) => {
  if (!values || values.length < period) return [];
  const k = 2/(period+1); const out=[]; let prev=values[0]; out.push(prev);
  for(let i=1;i<values.length;i++){ const cur=values[i]*k+prev*(1-k); out.push(cur); prev=cur; }
  return out;
};

// --- RSI ---
const rsi = (closes, period=14)=>{
  if (!closes || closes.length<=period) return [];
  let gains=0, losses=0;
  for(let i=1;i<=period;i++){ const ch=closes[i]-closes[i-1]; if(ch>0)gains+=ch; else losses-=ch; }
  let avgGain=gains/period, avgLoss=losses/period, out=[];
  for(let i=period;i<closes.length;i++){
    const rs=avgLoss===0?Infinity:avgGain/avgLoss;
    const v=rs===Infinity?100:100-100/(1+rs); out.push(isFinite(v)?v:50);
    const ch=closes[i]-closes[i-1];
    avgGain=((avgGain*(period-1))+(ch>0?ch:0))/period;
    avgLoss=((avgLoss*(period-1))+(ch<0?-ch:0))/period;
  }
  return out;
};

// --- ATR ---
const trueRanges=(h,l,c)=>h.map((hi,i)=>i===0?hi-l[i]:Math.max(hi-l[i],Math.abs(hi-c[i-1]),Math.abs(l[i]-c[i-1])));
const atr=(h,l,c,p=14)=>sma(trueRanges(h,l,c),p);

// --- Bollinger ---
const bollinger=(cl,p=20,std=2)=>{
  if(!cl||cl.length<p)return [];
  const ma=sma(cl,p), out=[];
  for(let i=p-1;i<cl.length;i++){
    const slice=cl.slice(i-p+1,i+1), mean=ma[i-p+1];
    const variance=slice.reduce((a,v)=>a+Math.pow(v-mean,2),0)/p;
    const sd=Math.sqrt(variance);
    out.push({upper:mean+sd*std,middle:mean,lower:mean-sd*std,bandwidth:mean?((sd*std*2)/mean)*100:0});
  }
  return out;
};

// --- ADX ---
const adx=(h,l,c,p=14)=>{
  if(h.length<p+1)return null;
  const tr=[], plusDM=[], minusDM=[];
  for(let i=1;i<h.length;i++){
    const up=h[i]-h[i-1], dn=l[i-1]-l[i];
    plusDM.push(up>dn&&up>0?up:0); minusDM.push(dn>up&&dn>0?dn:0);
    tr.push(Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1])));
  }
  const trN=sma(tr,p), plusDMN=sma(plusDM,p), minusDMN=sma(minusDM,p);
  if(!trN.length)return null;
  const plusDI=plusDMN.map((v,i)=>trN[i]===0?0:(100*v)/trN[i]);
  const minusDI=minusDMN.map((v,i)=>trN[i]===0?0:(100*v)/trN[i]);
  const dx=plusDI.map((p1,i)=>{const m=minusDI[i],den=p1+m;return den===0?0:(100*Math.abs(p1-m))/den;});
  const adxVals=sma(dx,p);
  return {adx:toNum(last(adxVals)),plusDI:toNum(last(plusDI)),minusDI:toNum(last(minusDI))};
};

// --- Market Structure ---
const marketStructure=(h,l,lookback=25,keep=5)=>{
  const swingHighs=[], swingLows=[];
  for(let i=lookback;i<h.length-lookback;i++){
    const hi=h[i], lo=l[i];
    if(h.slice(i-lookback,i+lookback+1).every(x=>hi>=x)) swingHighs.push({index:i,price:hi});
    if(l.slice(i-lookback,i+lookback+1).every(x=>lo<=x)) swingLows.push({index:i,price:lo});
  }
  let structure="RANGING";
  if(swingHighs.length>1&&swingLows.length>1){
    const h1=swingHighs[swingHighs.length-2], h2=swingHighs[swingHighs.length-1];
    const l1=swingLows[swingLows.length-2], l2=swingLows[swingLows.length-1];
    if(h2.price>h1.price&&l2.price>l1.price) structure="UPTREND";
    else if(h2.price<h1.price&&l2.price<l1.price) structure="DOWNTREND";
  }
  return {
    structure,
    support_levels: uniqSorted(swingLows.slice(-keep).map(s=>s.price),true),
    resistance_levels: uniqSorted(swingHighs.slice(-keep).map(s=>s.price),false),
    support: swingLows.length?toNum(swingLows.at(-1).price):null,
    resistance: swingHighs.length?toNum(swingHighs.at(-1).price):null
  };
};

// --- Fib ---
const fibonacci=(h,l,window=120)=>{
  if(!h.length||!l.length) return null;
  const hi=Math.max(...h.slice(-window)), lo=Math.min(...l.slice(-window)), r=hi-lo;
  return {
    swing_high:toNum(hi), swing_low:toNum(lo),
    retracements:{"0":hi,"236":hi-0.236*r,"382":hi-0.382*r,"500":hi-0.5*r,"618":hi-0.618*r,"786":hi-0.786*r,"1000":lo},
    extensions:{"1272":hi+1.272*r,"1618":hi+1.618*r,"2000":hi+2*r}
  };
};

// ============================================
// 🆕 VOLUME PROFILE (S-TIER) - Patrick Neil
// ============================================
const volumeProfile = (high, low, close, volume, priceLevels=50) => {
  if (!high || high.length < 10) return null;

  // Step 1: Price range
  const highestPrice = Math.max(...high);
  const lowestPrice = Math.min(...low);
  const priceRange = highestPrice - lowestPrice;
  const tickSize = priceRange / priceLevels;

  // Step 2: Initialize buckets
  const profile = Array(priceLevels).fill(0).map((_, idx) => ({
    price: lowestPrice + (idx * tickSize),
    volume: 0,
    buyVol: 0,
    sellVol: 0
  }));

  // Step 3: Distribute volume
  for (let i = 0; i < high.length; i++) {
    const lowBucket = Math.floor((low[i] - lowestPrice) / tickSize);
    const highBucket = Math.min(Math.floor((high[i] - lowestPrice) / tickSize), priceLevels - 1);
    const touchedLevels = highBucket - lowBucket + 1;
    const volPerLevel = volume[i] / touchedLevels;

    for (let j = lowBucket; j <= highBucket; j++) {
      if (j >= 0 && j < priceLevels) {
        profile[j].volume += volPerLevel;
        // Buy/Sell approximation
        if (close[i] > (i > 0 ? close[i-1] : close[i])) {
          profile[j].buyVol += volPerLevel;
        } else {
          profile[j].sellVol += volPerLevel;
        }
      }
    }
  }

  // Step 4: Find POC
  let maxVolIdx = 0, maxVol = 0;
  for (let i = 0; i < profile.length; i++) {
    if (profile[i].volume > maxVol) {
      maxVol = profile[i].volume;
      maxVolIdx = i;
    }
  }
  const POC = profile[maxVolIdx].price;

  // Step 5: Value Area (70% volume)
  const totalVol = profile.reduce((sum, p) => sum + p.volume, 0);
  const targetVol = totalVol * 0.70;
  let cumVol = profile[maxVolIdx].volume;
  let above = maxVolIdx + 1, below = maxVolIdx - 1;

  while (cumVol < targetVol && (above < priceLevels || below >= 0)) {
    const aboveVol = above < priceLevels ? profile[above].volume : 0;
    const belowVol = below >= 0 ? profile[below].volume : 0;

    if (aboveVol >= belowVol && above < priceLevels) {
      cumVol += aboveVol; above++;
    } else if (below >= 0) {
      cumVol += belowVol; below--;
    } else break;
  }

  const VAH = above > maxVolIdx ? profile[above - 1].price : profile[maxVolIdx].price;
  const VAL = below < maxVolIdx ? profile[below + 1].price : profile[maxVolIdx].price;

  // Step 6: HVN/LVN
  const avgVol = totalVol / priceLevels;
  const hvn = [], lvn = [];
  for (let i = 0; i < profile.length; i++) {
    if (profile[i].volume > avgVol * 1.5) {
      hvn.push({ price: toNum(profile[i].price), volume: toNum(profile[i].volume) });
    } else if (profile[i].volume < avgVol * 0.5) {
      lvn.push({ price: toNum(profile[i].price), volume: toNum(profile[i].volume) });
    }
  }

  // Step 7: Current price vs VP
  const lastClose = close[close.length - 1];
  let pricePosition = "INSIDE_VALUE";
  if (lastClose > VAH) pricePosition = "ABOVE_VALUE";
  else if (lastClose < VAL) pricePosition = "BELOW_VALUE";

  let pocDistance = Math.abs(lastClose - POC) / lastClose;
  let atPOC = pocDistance < 0.005; // within 0.5%

  return {
    POC: toNum(POC),
    value_area_high: toNum(VAH),
    value_area_low: toNum(VAL),
    value_area_range_pct: toNum(((VAH - VAL) / VAL) * 100),
    high_volume_nodes: hvn.slice(0, 5),
    low_volume_nodes: lvn.slice(0, 3),
    price_position: pricePosition,
    at_POC: atPOC,
    poc_distance_pct: toNum(pocDistance * 100),
    signal: atPOC ? "ENTRY_AT_POC" : (pricePosition === "ABOVE_VALUE" ? "BULLISH_BREAKOUT" : (pricePosition === "BELOW_VALUE" ? "BEARISH_BREAKDOWN" : "NEUTRAL"))
  };
};

// --- Prepare Kline ---
const prepareKlineData=(list)=>{
  if(!Array.isArray(list)||list.length<50)return null;
  const r=[...list].reverse();
  return {
    timestamps:r.map(k=>+k[0]), open:r.map(k=>+k[1]), high:r.map(k=>+k[2]),
    low:r.map(k=>+k[3]), close:r.map(k=>+k[4]), volume:r.map(k=>+k[5])
  };
};

// --- Main ---
const analyze15min=(d)=>{
  if(!d||!d.close.length) return {ready:false};
  const {high,low,close,volume}=d; const lastClose=close.at(-1);

  // Existing indicators
  const ema20=last(ema(close,20)), ema50=last(ema(close,50)), ema200=last(ema(close,200));
  const rsi14=last(rsi(close,14));
  const adxObj=adx(high,low,close,14);
  const bb=last(bollinger(close,20,2));
  const atr14=last(atr(high,low,close,14));
  const ms=marketStructure(high,low,25,5);
  const fib=fibonacci(high,low,120);

  // 🆕 NEW: Volume Profile (S-Tier)
  const vp = volumeProfile(high, low, close, volume, 50);

  return {
    ready: close.length>=200,
    valid_data: close.length>=200,
    prices:{close:toNum(lastClose)},
    ema:{ema20:toNum(ema20),ema50:toNum(ema50),ema200:toNum(ema200)},
    rsi:toNum(rsi14),
    rsi_signal:rsi14!=null?(rsi14>70?"OVERBOUGHT":(rsi14<30?"OVERSOLD":"NEUTRAL")):null,
    adx:adxObj,
    adx_signal:adxObj?.adx!=null?(adxObj.adx>25?"TRENDING":"WEAK"):null,
    atr:toNum(atr14),
    atr_pct:(atr14&&lastClose)?parseFloat(((atr14/lastClose)*100).toFixed(2)):null,
    bollinger:bb?{upper:toNum(bb.upper),middle:toNum(bb.middle),lower:toNum(bb.lower),bandwidth:bb.bandwidth}:null,
    market_structure:ms,
    fibs:fib,

    // 🆕 NEW: Volume Profile data
    volume_profile: vp,

    // 🆕 NEW: Enhanced signals combining VP
    enhanced_signals: vp ? {
      vp_signal: vp.signal,
      entry_quality: vp.at_POC ? "EXCELLENT (@ POC)" :
                     (vp.price_position === "INSIDE_VALUE" ? "GOOD (in value)" : "MODERATE"),
      hvn_support_resistance: vp.high_volume_nodes.length > 0 ? "YES" : "NO",
      confidence_boost: vp.at_POC ? "+5%" : (vp.price_position === "INSIDE_VALUE" ? "+3%" : "0%")
    } : null
  };
};

// --- Execution ---
try {
  const { result }=$input.item.json;
  const klineData=prepareKlineData(result.list);
  const features=analyze15min(klineData);
  return {
    json:{
      symbol:result.symbol,
      bybit_symbol:result.symbol,
      source:"ta_15m_with_vp",  // Changed source name
      tier: "S",  // Marking as S-tier analysis
      data:features
    }
  };
} catch(err){
  return {
    json:{
      symbol:$input.item.json.result?.symbol||"UNKNOWN",
      bybit_symbol:$input.item.json.result?.symbol||"UNKNOWN",
      source:"ta_15m_with_vp",
      data:{ready:false,error:err.message}
    }
  };
}

