  if (bybitFrac !== null && Number.isFinite(bybitFrac)) return bybitFrac * 100;
  const lcPct = safeNum(d.percent_change_1h, null);
  if (lcPct !== null && Number.isFinite(lcPct)) return lcPct;
  const last = safeNum(d.lastPrice, null);
  const prev = safeNum(d.prevPrice1h, null);
  if (last && prev) return ((last - prev) / prev) * 100;
  return 0;
}

