  } else if (btc_atr_pct > 3.0) {
    volatility_regime = "HIGH";
    vol_multiplier = 0.85;
  } else if (btc_atr_pct < 1.5) {
    volatility_regime = "LOW";
    vol_multiplier = 1.15;
  }

