  if (vpQuality === "GOLDEN") stats.vp_golden++;
  else if (vpQuality === "EXCELLENT") stats.vp_excellent++;
  else if (vpQuality === "GOOD") stats.vp_good++;

  console.log(`📊 ${symbol}${vpIndicator}: Score ${scoring.total}/100`);
