const errors = [];

if (!symbol) errors.push('Missing symbol');
if (!side) errors.push('Missing side');
if (!entry || entry <= 0) errors.push('Invalid entry price');
if (!stopLoss || stopLoss <= 0) errors.push('Invalid stop-loss price');
