    json: tradeRunnerRequest
}];

// =====================================================================
// WEB PAYLOAD CLEANER v3.0 — Public Full Data Mode
// - Keeps all meaningful analytics, TA, regime, RR, Alpha, Risk
// - Removes technical boilerplate, redundant or oversized arrays
// - Outputs one JSON array for HTTP POST to web backend
// =====================================================================

const round = (v, d = 4) => (v == null ? v : Number(v.toFixed(d)));

const cleanTrade = (t) => {
  const side = t.side?.toUpperCase() === "LONG" ? "BUY" : t.side?.toUpperCase() || "BUY";
  const lastTP = t.takeProfits?.length ? t.takeProfits[t.takeProfits.length - 1].price : null;
  const support = side === "BUY" ? t.stopLoss : lastTP;
  const resistance = side === "BUY" ? lastTP : t.stopLoss;

  // Alpha grade
  const alphaGrade =
    t.alphaScore >= 85 ? "A+" :
    t.alphaScore >= 75 ? "A" :
    t.alphaScore >= 65 ? "B" :
    t.alphaScore >= 50 ? "C" : "D";

  // Risk class
  const riskClass =
    t.risk_usdt >= 8 ? "HIGH" :
    t.risk_usdt >= 4 ? "MED" : "LOW";

  // Compact cleanup helper for TA blocks
  const cleanTA = (ta) => {
    if (!ta) return null;
    const {
      rsi, adx, atr, atr_pct, supertrend, ema, bollinger, market_structure, ichimoku
    } = ta;
    return {
      rsi,
      adx,
      atr,
      atr_pct,
      ema,
      supertrend,
      bollinger,
      ichimoku,
      market_structure,
    };
  };

  return {
    // ================= BASIC INFO =================
    symbol: t.symbol || t.bybit_symbol,
    name: t.name || t.symbol,
    side,
    regime: t._regime?.regime || "NEUTRAL",
    rr: round(t.rr, 2),
    leverage: round(t.leverage, 2),
    price: round(t.price || t.entry, 6),
    tier: t.tier,
    alphaScore: round(t.alphaScore || t.score, 1),
    alpha_grade: alphaGrade,
    risk_class: riskClass,
    tags: t.tags || [],
    reasons: t.reasons || [],
    risk_note: t.risk_note,

    // ================= MARKET DERIVED =================
    derived: {
      pct_change_1h: round(t.derived?.pct_change_1h),
      pct_change_24h: round(t.derived?.pct_change_24h),
      volatility: round(t.derived?.volatility),
      sentiment: round(t.derived?.sentiment),
      oi_ratio: round(t.derived?.oi_ratio),
      galaxy_score: round(t.derived?.galaxy),
      alt_rank: t.derived?.alt_rank,
      alt_rank_jump: t.derived?.alt_rank_jump,
      engagement_efficiency: t.derived?.engagement_efficiency,
      volume24h: t.derived?.volume24h,
      turnover24h: t.derived?.turnover24h,
      openInterestValue: t.derived?.openInterestValue,
      fundingRate: round(t.derived?.fundingRate)
    },

    // ================= TECHNICAL ANALYSIS =================
    ta_4h: cleanTA(t.ta_4h),
    ta_1h: cleanTA(t.ta_1h),
    ta_15m: cleanTA(t.ta_15m),

    // ================= SUPPORT/RESISTANCE =================
    levels: {
      support: round(support, 6),
      resistance: round(resistance, 6)
    },

    // ================= TRADE METADATA =================
    trade: {
      entry: round(t.entry, 6),
      stopLoss: round(t.stopLoss, 6),
      takeProfits: t.takeProfits?.map(tp => ({
        tp_id: tp.tp_id,
        price: round(tp.price, 6),
        size_pct: tp.size_pct
      })),
      allocated_usdt: round(t.allocated_usdt, 2),
      risk_usdt: round(t.risk_usdt, 2),
      liquidation_gap_pct: round(t.liquidation_gap_pct, 2),
      position_health_score: round(t.position_health_score, 2),
      qty: t.qty
    },

    // ================= STRATEGY / SLTP =================
    sltp_metadata: t.sltp_metadata ? {
      ...t.sltp_metadata,
      notes: undefined // remove notes (verbose)
    } : undefined,

    leverage_metadata: t.leverage_metadata ? {
      ...t.leverage_metadata,
      notes: undefined
    } : undefined,

    // ================= META =================
    _regime: {
      regime: t._regime?.regime,
      bullScore: t._regime?.bullScore,
      bearScore: t._regime?.bearScore,
      ms4h: t._regime?.ms4h,
      st1h: t._regime?.st1h,
      funding: t._regime?.funding
    },
    timestamp: t._meta?.timestamp || new Date().toISOString(),
    source: t._meta?.source || "AUTO"
  };
};

// Build array
const dashboardData = items.map(i => cleanTrade(i.json));

// Return single payload
return [{
  json: {
    signals: dashboardData,
    metadata: {
      source: "n8n",
      workflow: $workflow.name,
      execution_id: $execution.id,
      timestamp: new Date().toISOString(),
      count: dashboardData.length
    }
  }
}];

/**
 * NODE: Public Free Formatter v2.0
 * - Removes zero/empty fields
 * - Keeps only general + teaser fields
 * - Prepares web-safe JSON for public site
 */

function safeNum(v, d = 0) {
  const n = typeof v === 'string' ? parseFloat(v) : v;
  return Number.isFinite(n) ? n : d;
}

function cleanObject(obj) {
  const result = {};
  for (const [k, v] of Object.entries(obj)) {
    if (
      v === null ||
      v === undefined ||
      v === "" ||
      v === "N/A" ||
      (typeof v === "number" && v === 0)
    ) continue;
    result[k] = v;
  }
  return result;
}

const input = $input.all().map(i => i.json);
const free = [];

for (const coin of input) {
  const ta4h = coin.ta_4h || {};
  const struct = ta4h.market_structure || {};
  const derived = coin.derived || {};

  const item = {
    symbol: coin.symbol,
    name: coin.name,
    logo: coin.logo || coin.raw?.logo || null,
    price: safeNum(coin.price),

    alpha_score: safeNum(coin.score),
    rating_tier: coin.tier || undefined,

    daily_momentum: safeNum(derived.pct_change_24h),
    volatility_index: safeNum(derived.volatility),
    trade_flow_24h: safeNum(derived.volume24h),
    investor_sentiment: safeNum(derived.sentiment),

    social_strength: safeNum(derived.galaxy),
    market_quality: safeNum(derived.alt_rank),

    trend_bias: ta4h.market_structure?.structure,
    momentum_state: ta4h.rsi_signal,
    key_support: struct.support,
    key_resistance: struct.resistance,

    sector: coin.category_main || coin.raw?.categories || "general",
    signals: coin.tags || [],

    // Premium hook
    advanced_metrics: false,
    premium_hint: "Unlock detailed analytics & pro trader signals"
  };

  free.push(cleanObject(item));
}

// Sort by alpha_score descending
free.sort((a, b) => (b.alpha_score || 0) - (a.alpha_score || 0));

// Limit to 20 strongest coins
const result = free.slice(0, 20);

return result.map(x => ({ json: x }));
